let seed = Math.random() * 555;
let mySize, margin;
let num;
let myGraphic;
let palette;
let layers = [];
let speed = 3;
let layer_num, layer_x, layer_y;
let offset = 0;

function setup() {
	// pixelDensity(4);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight) * 0.9;
	margin = mySize / 100;
	createCanvas(mySize, mySize, WEBGL);
	ortho(-width / 2, width / 2, -height / 2, height / 2, -5000, 5000);
	myGraphic = createGraphics(mySize / 2, mySize / 2);
	frontGraphic = createGraphics(mySize / 2, mySize / 2);
	palette = random(colorScheme).colors.concat();
	angleMode(DEGREES);
	num = int(random(1, 1));
	layer_num = num;
	layer_w = width / layer_num;
	layer_h = height / layer_num;
	for (let i = 0; i < layer_num; i++) {
		for (let j = 0; j < layer_num; j++) {
			layers.push(new makeLayer(i * layer_w, j * layer_h, layer_w, 5));
		}
	}
	background(random(palette));
}

function draw() {
	randomSeed(seed);
	orbitControl();
	background(random(palette));
	createmyGraphic();

	for (let i = 0; i < 6; i += 5) {
    translate(0, 0, -40);
    box(1450);
	}

	for (let l of layers) {
		l.run();
	}
	offset += 1 / random([1, 2, 4]);
}

