// === Tab: makeLayer ===

let ry = 0;
let rdir = 1;
let rMax = 45;

class makeLayer {
	constructor(x, y, size, rotate) {
		this.x = x;
		this.y = y;
		this.size = size;
		this.rotate = rotate;
		this.settime();
		this.tog = 0;
		this.t = 0;
		this.t1 = 0;
		this.speed = int(random(1, 6));
	}

	display() {
		noStroke();
		texture(myGraphic);

		push();
		// rotateX(frameCount / 5 * random([-1, 1]));
		// rotateX(-ry);
		rotateY(ry);
		this.updateRotateY();
		rotateZ(random(360)+frameCount / 20 * random([-1, 1]));

		translate(-width * 0.5 + this.size / 2 + this.x, -height * 0.5 + this.size / 2 + this.y, 0);

		let lavaShape = int(random(3, 6));
		let torusD = this.size * 1;
		let lavaLight_n = 8;
		// sphere(torusD/random(10, 50));
		for (let i = 0; i < lavaLight_n; i++) {
			let lavaLight_s = this.size / random(12, 6);
			// rotateX(random(TAU) + offset / 10);
			// rotateY(random(TAU) + offset / 10);
			// rotateZ(random([0,180]));
			this.updateRotate();
			push();
			translate(0, 0, i * lavaLight_s / lavaLight_n);
			plane(torusD / lavaLight_n * (lavaLight_n - i) * 2);
			// box(torusD / lavaLight_n * (lavaLight_n - i)*2, 2, 2);
			// torus(torusD / lavaLight_n * (lavaLight_n - i), lavaLight_s / lavaLight_n, 60, lavaShape);
			pop();
		}

		pop();

		for (let i = 0; i < 20; i++) {
			push();
			rotateX(frameCount / 5 * random([-1, 1]));
			rotateY(frameCount / 5 * random([-1, 1]));
			rotateZ(frameCount / 5 * random([-1, 1]));
			translate(random(-1, 1) * mySize / 2, random(-1, 1) * mySize / 2, random(-1, 1) * mySize / 2);
			rotateX(random(TAU));
			rotateY(random(TAU));
			rotateZ(random(TAU));
			// box(100*random(1, 5));
			pop();
		}

	}

	settime() {
		this.t = -int((map(speed, 1, 5, 100, 500)));
		this.t1 = map(speed, 1, 5, 500, 100);
	}

	// rotateY(frameCount / 5 * random([-1, 1]));
	updateRotateY() {

		if (ry < rMax && rdir == 1) {
			ry += 1/10;
		}else if(ry >= rMax){
			rdir = -1;
		}
		if (ry > -rMax && rdir == -1) {
			ry -= 1/10;
		}else if(ry <= -rMax){
			rdir = 1;
		}
	}

	updateRotate() {
		switch (int(random(6))) {
			case 0:
				rotateZ(-this.rotate / random([1, 0.5]));
				break;
			case 1:
				rotateZ(this.rotate / random([1, 0.5]));
				break;
			case 2:
				rotateZ(this.rotate);
				break;
			case 3:
				rotateZ(-this.rotate);
				break;
			case 4:
				rotateZ(this.rotate);
				break;
			case 5:
				rotateZ(this.rotate);
				break;
		}
	}

	update1() {
		if (this.t >= 0 && this.t < this.t1) {
			let easePar = norm(this.t, 0, this.t1 - 1);
			this.rotate = lerp(-90, 90, Easing.easeOutQuint(easePar));
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t += random([1, 2, 4]);
	}

	update3() {
		if (this.t >= 0 && this.t < this.t1) {
			var easePar = norm(this.t, 0, this.t1 - 1);
			this.rotate = lerp(-90, 90, Easing.easeOutCirc(easePar));
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t += random([1, 2, 4]);
	}

	update2() {
		if (this.t >= 0 && this.t < this.t1) {
			var easePar = norm(this.t, 0, this.t1 - 1);
			this.rotate = lerp(-90, 90, Easing.easeOutBack(easePar));
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t += random([1, 2, 4]);
	}

	run() {
		this.display();

		// switch (int(random(3))) {
		// 	case 0:
		// 		this.update1();
		// 		break;
		// 	case 1:
		// 		this.update2();
		// 		break;
		// 	case 2:
		// 		this.update3();
		// 		break;
		// }
	}
}

// === Tab: myGraphic ===

function createmyGraphic() {
	myGraphic.background(random(palette));
	myGraphic.strokeCap(SQUARE);
	myGraphic.stroke(random(palette));
	myGraphic.noFill();
	// myGraphic.drawingContext.setLineDash([10, 20, 30]);
	myGraphic.drawingContext.lineDashOffset = offset / 1;
	if (int(seed) % 2 == 0) {
		myGraphic.strokeWeight(myGraphic.height / random([1, 1, 2]));
		myGraphic.line(myGraphic.width / 2, myGraphic.height / 1, myGraphic.width / 2, 0);
	}
	if (int(seed) % 2 == 1) {
		myGraphic.strokeWeight(myGraphic.width / random([1, 1, 2]));
		myGraphic.line(myGraphic.width, myGraphic.height / 2, 0, myGraphic.height / 2);
	}
	drawRect(0, 0, myGraphic.width, myGraphic.height, myGraphic);
}

function drawRect(x, y, w, h, p) {
	// first draw a rectangle
	p.strokeCap(SQUARE);
	p.stroke(random(palette));
	p.strokeWeight(w / random([1, 2]));
	p.noFill();
	p.drawingContext.setLineDash([5, 10, 15]);
	p.drawingContext.lineDashOffset = offset / random([1, 2]);
	p.line(x, y + h / 2, x + w / 2, y + h / 2)

	// then figure out if we need to draw another
	let splitWidth = random(1) > 0.5;
	let splitWhere = random(0.1, 0.6);

	// if we're splitting the width
	if (splitWidth && w > myGraphic.width / random([5, 4, 6])) {
		drawRect(x, y, w * splitWhere, h, p);
		drawRect(x + (w * splitWhere), y, w * (1 - splitWhere), h, p);
	}
	// else if we're splitting the height
	else if (h > myGraphic.height / random([4, 8, 10])) {
		drawRect(x, y, w, h * splitWhere, p);
		drawRect(x, y + (h * splitWhere), w, h * (1 - splitWhere), p);
	}
}

// === Tab: Easing ===
class Easing {
	static easeInSine(x) {
		return 1 - Math.cos((x * Math.PI) / 2);
	}

	static easeOutSine(x) {
		return Math.sin((x * Math.PI) / 2);
	}

	static easeInOutSine(x) {
		return -(Math.cos(Math.PI * x) - 1) / 2;
	}

	static easeInQuad(x) {
		return x * x;
	}

	static easeOutQuad(x) {
		return 1 - (1 - x) * (1 - x);
	}

	static easeInOutQuad(x) {
		return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
	}

	static easeInCubic(x) {
		return x * x * x;
	}

	static easeOutCubic(x) {
		return 1 - Math.pow(1 - x, 3);
	}

	static easeInOutCubic(x) {
		return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
	}

	static easeInQuart(x) {
		return x * x * x * x;
	}

	static easeOutQuart(x) {
		return 1 - Math.pow(1 - x, 4);
	}

	static easeInOutQuart(x) {
		return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
	}

	static easeInQuint(x) {
		return x * x * x * x * x;
	}

	static easeOutQuint(x) {
		return 1 - Math.pow(1 - x, 5);
	}

	static easeInOutQuint(x) {
		return x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2;
	}

	static easeInExpo(x) {
		return x === 0 ? 0 : Math.pow(2, 10 * x - 10);
	}

	static easeOutExpo(x) {
		return x === 1 ? 1 : 1 - Math.pow(2, -10 * x);
	}

	static easeInOutExpo(x) {
		return x === 0 ?
			0 :
			x === 1 ?
			1 :
			x < 0.5 ?
			Math.pow(2, 20 * x - 10) / 2 :
			(2 - Math.pow(2, -20 * x + 10)) / 2;
	}

	static easeInCirc(x) {
		return 1 - Math.sqrt(1 - Math.pow(x, 2));
	}

	static easeOutCirc(x) {
		return Math.sqrt(1 - Math.pow(x - 1, 2));
	}

	static easeInOutCirc(x) {
		return x < 0.5 ?
			(1 - Math.sqrt(1 - Math.pow(2 * x, 2))) / 2 :
			(Math.sqrt(1 - Math.pow(-2 * x + 2, 2)) + 1) / 2;
	}

	// バックイージングには追加のパラメータ（c1とc3）が必要です。
	static easeInBack(x) {
		const c1 = 1.70158;
		const c3 = c1 + 1;
		return c3 * x * x * x - c1 * x * x;
	}

	static easeOutBack(x) {
		var c1 = 1.70158;
		var c3 = c1 + 1;
		return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
	}

	static easeInOutBack(x) {
		var c1 = 1.70158;
		const c2 = c1 * 1.525;
		return x < 0.5 ?
			(Math.pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2 :
			(Math.pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;
	}
}

